+  return {
+    fileId: input.fileId,
+    versionId: input.versionId,
+    intent: input.intent,
+    state: input.state,
+    mimeType: input.mimeType,
+    name: input.name,
+    size: input.size,
+    source: {
+      mode: 'placeholder',
+      placeholderKind: input.placeholderKind,
+    },
